'use strict';
let adventureReturn=null,recipeSlots=[null,null],recipeMaterialLimit=80;
const adventureEl=id=>document.getElementById(id);
function adventureNode(tag,cls,text){const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n;}
function openAdventure(id){adventureReturn=document.activeElement;pausePlayerOverlay();adventureEl(id).classList.remove('hidden');adventureEl(id).querySelector('.editor-panel').scrollTop=0;adventureEl(id).querySelector('.editor-title button').focus();}
window.closeAdventure=id=>{adventureEl(id).classList.add('hidden');resumePlayerEngine();if(adventureReturn?.isConnected)adventureReturn.focus();};
window.renderAdventureSummary=()=>{
 const completed=KanjiGoals.missions.filter(m=>KanjiGoals.progress(gameState,m.id).complete).length,claims=gameState.collectionClaims||[];
 adventureEl('collection-goal-summary').textContent=`達成 ${completed} / ${KanjiGoals.missions.length}・報酬受取 ${claims.length}`;
 adventureEl('recipe-book-summary').textContent=`レシピ発見 ${(gameState.recipeDiscoveries||[]).length} / ${KanjiGoals.recipes.length}`;
};
window.openCollectionGoals=()=>{renderCollectionGoals();openAdventure('modal-collection-goals');};
function renderCollectionGoals(){
 const box=adventureEl('collection-goal-list');box.replaceChildren();const found=new Set(gameState.characterDiscoveries||[]);
 for(const m of KanjiGoals.missions){const p=KanjiGoals.progress(gameState,m.id),card=adventureNode('article','adventure-card'),heading=adventureNode('h3','',m.name),progress=adventureNode('p','adventure-meta',`${p.found} / ${p.total}種類・報酬 ${m.coins}文`),letters=adventureNode('div','adventure-letters');
  for(const char of m.chars.slice(0,30)){const chip=adventureNode('span','kanji-font',char);chip.dataset.found=String(found.has(char));chip.setAttribute('aria-label',`${char}：${found.has(char)?'入手済み':'未入手'}`);letters.append(chip);}if(m.chars.length>30)letters.append(adventureNode('p','adventure-meta','水準内のすべての文字が対象です。')) ;
  const button=adventureNode('button','inventory-action',p.claimed?'受取済み':p.complete?'報酬を受け取る':'収集途中');button.type='button';button.dataset.claim=m.id;button.disabled=!p.complete||p.claimed;button.onclick=()=>{try{const mission=KanjiGoals.claim(gameState,m.id);saveState();renderCollectionGoals();playSound('win');showToast(`「${mission.name}」達成！\n${mission.coins}文を受け取りました。\n報酬を2・5・8種類受け取ると専用アイコン枠が解放されます。`);}catch{renderCollectionGoals();}};card.append(heading,progress,letters,button);box.append(card);
 }
}
window.openTeamLinks=()=>{renderTeamLinks();openAdventure('modal-team-links');};
function renderTeamLinks(){const box=adventureEl('team-link-list'),current=gameState.deck.map(id=>gameState.inventory.find(i=>i.instanceId===id)).filter(Boolean),active=KanjiTeamLinks.active(current);box.replaceChildren();
 for(const link of KanjiTeamLinks.catalogue){const copies=link.chars.map(char=>gameState.inventory.filter(i=>i.char===char).sort((a,b)=>KanjiInventory.totalExp(b)-KanjiInventory.totalExp(a))[0]),available=copies.every(Boolean),card=adventureNode('article','adventure-card'),letters=adventureNode('div','adventure-letters');for(let n=0;n<link.chars.length;n++){const chip=adventureNode('span','kanji-font',link.chars[n]);chip.dataset.found=String(!!copies[n]);letters.append(chip);}const button=adventureNode('button','inventory-action',active?.id===link.id?'編成中':available?'この連携で編成':'所持文字が足りません');button.type='button';button.dataset.link=link.id;button.disabled=!available||active?.id===link.id;button.onclick=()=>{gameState.deck=copies.map(i=>i.instanceId);saveState();renderDeckSlots();renderCollection();updateBattleDeckSummary();renderTeamLinks();};card.append(adventureNode('h3','',link.name),letters,adventureNode('p','',`3体とも${KanjiTeamLinks.effect(link)}`),button);box.append(card);}
}
window.openRecipeWorkbench=()=>{recipeSlots=[null,null];recipeMaterialLimit=80;adventureEl('recipe-material-search').value='';renderRecipeWorkbench();openAdventure('modal-recipes');};
window.filterRecipeMaterials=()=>{recipeMaterialLimit=80;renderRecipeWorkbench();};
window.showMoreRecipeMaterials=()=>{recipeMaterialLimit+=80;renderRecipeWorkbench();};
window.selectRecipeMaterial=id=>{const item=gameState.inventory.find(i=>i.instanceId===id);if(!item||KanjiInventory.protectedItem(item,gameState.deck))return;const existing=recipeSlots.indexOf(id);if(existing>=0)recipeSlots[existing]=null;else{const empty=recipeSlots.indexOf(null);if(empty<0)return;recipeSlots[empty]=id;}renderRecipeWorkbench();};
function renderRecipeWorkbench(){
 recipeSlots=recipeSlots.map(id=>gameState.inventory.some(i=>i.instanceId===id&&!KanjiInventory.protectedItem(i,gameState.deck))?id:null);
 const slots=adventureEl('recipe-material-slots');slots.replaceChildren();for(let n=0;n<2;n++){const item=gameState.inventory.find(i=>i.instanceId===recipeSlots[n]),button=adventureNode('button','recipe-slot',item?`${item.char}　Lv.${item.level}`:`素材${n+1}を選択`);button.type='button';button.setAttribute('aria-label',`レシピ素材${n+1}${item?'を解除':''}`);button.onclick=()=>{recipeSlots[n]=null;renderRecipeWorkbench();};slots.append(button);}
 const plan=KanjiInventory.recipePlan(gameState,...recipeSlots),known=plan.recipe&&(gameState.recipeDiscoveries||[]).includes(plan.recipe.id),preview=adventureEl('recipe-preview');
 preview.textContent=plan.recipe?`${known?`結果：「${plan.recipe.result}」`:'未発見のレシピが反応しています。結果は錬成して発見。'}\n素材2体を消費・${plan.recipe.cost}文。育成経験値を継承。`:recipeSlots.every(Boolean)?'この組み合わせのレシピはありません。素材は消費しません。':'素材を2体選んでください。同じ文字を使う場合も2体必要です。';
 const action=adventureEl('btn-execute-recipe');action.disabled=!plan.operations.length||gameState.coins<(plan.recipe?.cost||0);action.textContent=plan.recipe&&gameState.coins<plan.recipe.cost?`${plan.recipe.cost}文が必要です`:'この2体で組み合わせ錬成';
 const grid=adventureEl('recipe-material-grid');grid.replaceChildren();const query=adventureEl('recipe-material-search').value.trim(),available=gameState.inventory.filter(i=>!KanjiInventory.protectedItem(i,gameState.deck)&&(!query||i.char.includes(query)));for(const item of available.slice(0,recipeMaterialLimit)){const b=adventureNode('button','recipe-material',`${item.char}　Lv.${item.level}`);b.type='button';b.dataset.materialId=item.instanceId;b.setAttribute('aria-pressed',String(recipeSlots.includes(item.instanceId)));b.disabled=recipeSlots.every(Boolean)&&!recipeSlots.includes(item.instanceId);b.onclick=()=>selectRecipeMaterial(item.instanceId);grid.append(b);}if(!available.length)grid.append(adventureNode('p','adventure-meta',query?'該当する素材がありません。':'選べる素材がありません。素材にする文字のロック・編成を解除してください。'));
 adventureEl('recipe-material-count').textContent=`選べる素材 ${available.length}体・${Math.min(available.length,recipeMaterialLimit)}体を表示`;adventureEl('btn-recipe-material-more').hidden=available.length<=recipeMaterialLimit;
 const book=adventureEl('recipe-discovery-list');book.replaceChildren();for(const recipe of KanjiGoals.recipes){const found=(gameState.recipeDiscoveries||[]).includes(recipe.id),card=adventureNode('article','adventure-card recipe-entry');card.dataset.recipe=recipe.id;card.append(adventureNode('h3','',found?`${recipe.materials.join(' ＋ ')} ＝ ${recipe.result}`:'未発見のレシピ'),adventureNode('p','',found?'発見済み・何度でも作れます':recipe.hint));book.append(card);}
 adventureEl('recipe-found-count').textContent=`発見 ${(gameState.recipeDiscoveries||[]).length} / ${KanjiGoals.recipes.length}`;
}
window.executeRecipe=()=>{const plan=KanjiInventory.recipePlan(gameState,...recipeSlots);if(!plan.operations.length)return;const before={inventory:gameState.inventory.slice(),characterDiscoveries:(gameState.characterDiscoveries||[]).slice()};let outcome;try{outcome=KanjiInventory.executePlan(gameState,plan,{getReadings:getRealReadings,catalogue:KANJI_DATABASE,createId:newInstanceId,onCreated:(item,context)=>KanjiCollection.synthesisResult(item,gameState.autoLockSettings,context.inventory,getRealReadings)});}catch(error){renderRecipeWorkbench();showToast(error.message==='coins'?`${plan.recipe.cost}文が必要です。`:'素材が変更されました。ロック・編成と素材を確認してください。');return;}const first=!(gameState.recipeDiscoveries||[]).includes(plan.recipe.id);recipeSlots=[null,null];commitInventoryOutcome(outcome);renderRecipeWorkbench();presentSynthesis(before,plan,outcome,{title:first?'新レシピ発見！':'組み合わせ錬成',note:`${plan.recipe.materials.join(' ＋ ')} ＝ 「${plan.recipe.result}」。${plan.recipe.cost}文・素材2体を消費し、育成経験値を継承しました。`});};
window.refreshCollectionAdventure=()=>{renderAdventureSummary();if(!adventureEl('modal-collection-goals').classList.contains('hidden'))renderCollectionGoals();if(!adventureEl('modal-recipes').classList.contains('hidden'))renderRecipeWorkbench();if(!adventureEl('modal-team-links').classList.contains('hidden'))renderTeamLinks();};
